from os import path

from taf.ul.alarms_watchdog import Alarm
from taf.ul.alarms_watchdog.exceptions import DisallowedAlarmsDetected
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_operation, log_result, log_exception
from taf.rfrl.procedures.resources.python.alarms.AlarmsManager import AlarmsManager
from taf.rfrl.procedures.resources.python.LogCollection import LogCollection
from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine


SLEEPING_CELL_ALARM_ID = '7114'
SLEEPING_CELL_FAULT_ID = '4547'
SLEEPING_CELL_FAULT_NAME = 'Sleeping Cell Detection Due To Degraded RACH Setup Attempts'
SLEEPING_CELL_ALARM = Alarm(alarm_id=SLEEPING_CELL_ALARM_ID,
                            fault_id=SLEEPING_CELL_FAULT_ID,
                            fault_name=SLEEPING_CELL_FAULT_NAME)
SLEEPING_CELL_SNAPSHOT_NAME = 'sleeping_cell_snapshot.zip'

_sleeping_cell_alarm_manager = AlarmsManager()


@log_input_and_output
def activate_sleeping_cell_detection(tl, log_dir='/tmp'):
    """
    Starts event watching for activation of sleeping cell alarm and triggers snapshot collection via telnet
    when alarm is detected.
    :param tl: configuration object of whole testline on which detection will be activated
    :type tl: taf.config.testline
    :param log_dir: path to directory where collected snapshot will be saved; defaults to '/tmp'
    :type log_dir: str
    """
    log_operation('Activating sleeping cell detection')
    log_collector = LogCollection()
    bts_type = TestLine().get_type_of_setup()
    on_gnb = True if bts_type == 'GNB' else False
    on_enb = True if bts_type == 'ENB' else False
    _sleeping_cell_alarm_manager.run_when_alarm_detected(trigger_alarms=[SLEEPING_CELL_ALARM],
                                                         callback=log_collector.collect_snapshot_via_telnet_connection,
                                                         local_path=path.join(log_dir, SLEEPING_CELL_SNAPSHOT_NAME))

    _sleeping_cell_alarm_manager.start_alarms_watchdog(tl=tl, log_dir=log_dir, on_enb=on_enb, on_gnb=on_gnb)


@log_input_and_output
def check_for_detected_sleeping_cell():
    """
    Stops event watching for activation of sleeping cell alarm and checks, whether it was detected
    since event watch was started.
    :raises DisallowedAlarmsDetected: if sleeping cell alarm has been detected
    """
    bts_type = TestLine().get_type_of_setup()
    for detected_alarm in _sleeping_cell_alarm_manager.get_detected_alarms(bts_type=bts_type):
        if _is_sleeping_cell_alarm_detected(detected_alarm):
            log_exception(
                'Sleeping cell detected, {} will be collected to logs dir'.format(SLEEPING_CELL_SNAPSHOT_NAME))
            _sleeping_cell_alarm_manager.stop_watching_alarms()
            raise DisallowedAlarmsDetected('\n{}'.format(detected_alarm))

    log_result('Sleeping cell not detected')
    _sleeping_cell_alarm_manager.stop_watching_alarms(bts_type=bts_type)


def _is_sleeping_cell_alarm_detected(detected_alarm):
    return all([detected_alarm.alarm_id == SLEEPING_CELL_ALARM_ID,
                detected_alarm.fault_id == SLEEPING_CELL_FAULT_ID,
                detected_alarm.fault_name == SLEEPING_CELL_FAULT_NAME])
